package at.hausgarten.service;

import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import org.json.*;
import java.util.*;

/** Atomic, read-only projection for the UI review and the commit-time comparison. */
final class InvoiceIssueReviewSnapshot {
    static JSONObject capture(PixelLocalStore store,String invoiceId)throws Exception {
        SQLiteDatabase database=store.getReadableDatabase();database.beginTransaction();try{
            // Avoid getState(): reading a review must neither materialize legacy PDFs nor
            // create timer review events. Reuse the same preparation and journal projection.
            JSONObject master=store.rawSnapshot("{}");PixelLocalStore.removeSnapshotPhotoBinaries(master);PixelDriveState.prepare(master);store.seedServiceCatalog(master);LocalTestCleanup.overlay(store,master);JSONObject authority=new LocalAuthorityGuard(store.appContext()).current();if(!authority.optString("mode").equals("LEGACY_DRIVE"))master.put("processing_engine",LocalAuthorityRules.ENGINE).put("local_contract_version",LocalAuthorityRules.CONTRACT);
            JSONArray pending=DriveJournalRules.union(store.pendingActions(),master.optJSONArray("drive_review_actions"));JSONObject effective=SnapshotProjection.effective(new JSONObject().put("master",master).put("pending",pending));JSONArray blockers=new JSONArray();try{LocalBillingProjection.apply(database,effective);}catch(Exception invalid){effective.remove("local_billing_sources");blockers.put(new JSONObject().put("code","LOCAL_BILLING_SOURCE_REVIEW_REQUIRED").put("message","Der aktuelle lokale Leistungs- und Restmengenstand benötigt Prüfung. Keine neue Rechnung freigeben."));}JSONObject dependencies=new JSONObject().put("formatVersion",1).put("authority",authority).put("blockers",blockers).put("worklog_allocations_by_invoice",ledger(database,"local_invoice_sources:",blockers)).put("material_allocations_by_invoice",ledger(database,"local_invoice_material_sources:",blockers)),movements=new JSONObject(),reversals=new JSONObject();
            JSONObject invoice=OwnerJournalRules.findOrNull(effective.optJSONArray("invoices"),invoiceId);describeOriginal(invoice,blockers);if(invoice!=null&&!invoice.optString("correction_of").isEmpty())describeOriginal(OwnerJournalRules.findOrNull(effective.optJSONArray("invoices"),invoice.getString("correction_of")),blockers);JSONArray positions=invoice==null||invoice.optString("document_type").equals("cancellation")?null:invoice.optJSONArray("positions");Set<String> ids=new TreeSet<>();for(int i=0;positions!=null&&i<positions.length();i++){JSONObject position=positions.optJSONObject(i);if(position!=null&&position.optString("source_type").equals("material_movement")&&!position.optString("source_id").isEmpty())ids.add(position.getString("source_id"));}
            for(String id:ids){String raw=DatabaseBackupSnapshot.ownerValue(database,"revier:v1:entity:material_movement:"+id,"");if(!raw.isEmpty())try{JSONObject movement=new JSONObject(raw);RevierRules.version(movement);if(!id.equals(movement.getString("id")))throw new IllegalArgumentException();movements.put(id,movement);}catch(Exception invalid){blockers.put(new JSONObject().put("code","INVOICE_MATERIAL_SOURCE_INVALID").put("message","Eine Materialquelle ist beschädigt oder benötigt eine neuere Appversion. Die Einsatzdokumentation prüfen.").put("entity_type","material_movement").put("id",id));}reversals.put(id,DatabaseBackupSnapshot.ownerValue(database,"revier:v1:reversed:"+id,""));}
            dependencies.put("material_movements",movements).put("material_reversals",reversals);JSONObject result=InvoiceIssueReviewRules.capture(effective,invoiceId,dependencies);database.setTransactionSuccessful();return result;
        }finally{database.endTransaction();}
    }
    private static void describeOriginal(JSONObject invoice,JSONArray blockers)throws Exception {if(invoice==null||invoice.optString("pdf_base64").isEmpty())return;try{LegacyPdfAttachment.describe(invoice);invoice.remove("pdf_base64");}catch(Exception invalid){blockers.put(new JSONObject().put("code","INVOICE_ORIGINAL_REVIEW_REQUIRED").put("message","Das vorhandene Original-PDF ist nicht zuverlässig lesbar. Originalnachweis prüfen; keine Ersatzdatei erzeugen.").put("entity_type","invoice").put("id",invoice.optString("id")));}}
    private static JSONObject ledger(SQLiteDatabase database,String prefix,JSONArray blockers)throws Exception {JSONObject result=new JSONObject();try(Cursor rows=database.rawQuery("SELECT key,value FROM owner_state WHERE key>=? AND key<? ORDER BY key",new String[]{prefix,prefix+'\uffff'})){while(rows.moveToNext()){String id=rows.getString(0).substring(prefix.length());try{result.put(id,new JSONObject(rows.getString(1)));}catch(Exception invalid){result.put(id,JSONObject.NULL);blockers.put(new JSONObject().put("code","INVOICE_SOURCE_LEDGER_INVALID").put("message","Eine lokale Leistungszuordnung ist beschädigt. Vor einer neuen Ausgabe den Belegbezug prüfen.").put("entity_type","invoice").put("id",id));}}}return result;}
    private InvoiceIssueReviewSnapshot(){}
}
